class ExactStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_order_pending = False
        self.aapl_order_pending = False

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_close_samples = 0

    def OnData(self, data):
        spy_bar = self._get_bar(data, self.spy)
        aapl_bar = self._get_bar(data, self.aapl)
        ibm_bar = self._get_bar(data, self.ibm)
        bac_bar = self._get_bar(data, self.bac)
        aig_bar = self._get_bar(data, self.aig)

        spy_up_cross = False
        spy_down_cross = False

        if spy_bar is not None and self.spy_sma.IsReady:
            today_spy_close = float(spy_bar.Close)
            today_spy_sma = float(self.spy_sma.Current.Value)

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
            ):
                spy_up_cross = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and today_spy_close > today_spy_sma
                )
                spy_down_cross = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and today_spy_close < today_spy_sma
                )

            self.previous_spy_close = today_spy_close
            self.previous_spy_sma = today_spy_sma

        if aapl_bar is not None:
            today_aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if today_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = today_aapl_close
            self.aapl_close_samples += 1

        if self.IsWarmingUp:
            return

        if any(bar is None for bar in (spy_bar, aapl_bar, ibm_bar, bac_bar, aig_bar)):
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
        )

        aapl_red_three_days = (
            self.aapl_close_samples >= 4
            and self.aapl_red_streak >= 3
        )

        # Evaluate sells before buys.
        if (
            self.spy_lot > 0
            and not self.spy_order_pending
            and spy_down_cross
        ):
            self._submit_spy_order(-self.spy_lot, "A_SELL")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and aapl_rsi_above_60
        ):
            self._submit_aapl_order(-self.aapl_lot, "B_SELL")

        # Strategy A buy.
        if (
            self.spy_lot == 0
            and not self.spy_order_pending
            and spy_up_cross
        ):
            close = float(spy_bar.Close)
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / close)

            if quantity > 0:
                self._submit_spy_order(quantity, "A_BUY")

        # Strategy B buy.
        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and aapl_red_three_days
            and float(self.Portfolio.Cash) >= 20000
        ):
            close = float(aapl_bar.Close)
            quantity = int(20000 / close)

            if quantity > 0:
                self._submit_aapl_order(quantity, "B_BUY")

    def OnOrderEvent(self, orderEvent):
        order = self.Transactions.GetOrderById(orderEvent.OrderId)

        if order is None:
            return

        tag = order.Tag
        fill_quantity = int(orderEvent.FillQuantity)

        if tag == "A_BUY":
            if fill_quantity > 0:
                self.spy_lot += fill_quantity
            if orderEvent.Status == OrderStatus.Filled:
                self.spy_order_pending = False
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_order_pending = False

        elif tag == "A_SELL":
            if fill_quantity < 0:
                self.spy_lot = max(0, self.spy_lot + fill_quantity)
            if orderEvent.Status == OrderStatus.Filled:
                self.spy_order_pending = False
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_order_pending = False

        elif tag == "B_BUY":
            if fill_quantity > 0:
                self.aapl_lot += fill_quantity
            if orderEvent.Status == OrderStatus.Filled:
                self.aapl_order_pending = False
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.aapl_order_pending = False

        elif tag == "B_SELL":
            if fill_quantity < 0:
                self.aapl_lot = max(0, self.aapl_lot + fill_quantity)
            if orderEvent.Status == OrderStatus.Filled:
                self.aapl_order_pending = False
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.aapl_order_pending = False

    def _get_bar(self, data, symbol):
        if data.Bars.ContainsKey(symbol):
            return data.Bars[symbol]
        return None

    def _submit_spy_order(self, quantity, tag):
        self.spy_order_pending = True
        self.MarketOrder(self.spy, quantity, tag=tag)

    def _submit_aapl_order(self, quantity, tag):
        self.aapl_order_pending = True
        self.MarketOrder(self.aapl, quantity, tag=tag)
