        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        bars = {}
        all_present = True

        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]
            else:
                all_present = False

        previous_spy_close = self.previous_closes.get(self.spy)
        previous_spy_sma_ready = self.spy_sma.IsReady
        previous_spy_sma = self.spy_sma.Current.Value

        previous_aapl_close = self.previous_closes.get(self.aapl)

        if self.spy in bars:
            self.spy_sma.Update(bars[self.spy].EndTime, bars[self.spy].Close)

        if self.aapl in bars:
            self.aapl_rsi.Update(bars[self.aapl].EndTime, bars[self.aapl].Close)

            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif bars[self.aapl].Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        for symbol, bar in bars.items():
            self.previous_closes[symbol] = bar.Close

        if not all_present:
            return

        spy_close = bars[self.spy].Close

        spy_crossed_above = (
            previous_spy_close is not None
            and previous_spy_sma_ready
            and self.spy_sma.IsReady
            and previous_spy_close <= previous_spy_sma
            and spy_close > self.spy_sma.Current.Value
        )

        spy_crossed_below = (
            previous_spy_close is not None
            and previous_spy_sma_ready
            and self.spy_sma.IsReady
            and previous_spy_close >= previous_spy_sma
            and spy_close < self.spy_sma.Current.Value
        )

        # Evaluate all sells before any buys.
        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A sell"
            )

        if (
            self.strategy_b_lot > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="Strategy B sell"
